// TRACK-B association-only: SHADOW preserves the original sorted-edge execution,
// including failed native corrections. ACTIVE tries selected edges, then still
// admissible original alternatives; each pair is corrected at most once.
const trackBAttempts=trackBSelection.active?[...trackBSelection.pairs,...pairs]:pairs,trackBTried=trackBSelection.active?new Map():null;
for(const q of trackBAttempts){
  if(usedTracks.has(q.id)||usedPlots.has(q.i))continue;
  if(trackBSelection.active){
    if(trackBSelection.heldPlots.has(q.i)||trackBSelection.heldTracks.has(q.id)||q.sanity?.ok===false)continue;
    let tried=trackBTried.get(q.i);if(!tried){tried=new Set();trackBTried.set(q.i,tried);}if(tried.has(q.id))continue;tried.add(q.id);
  }
  if(apply(q.id,plots[q.i],false)){usedTracks.add(q.id);usedPlots.add(q.i);}
}
